package com.bank.directory;

import java.util.*;
import java.util.logging.*;

public class DirectoryDemo {
    private static final Logger log = Logger.getLogger("Directory");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", "Trading", 1200000),
            new Employee("Sneha", "Trading", 1500000),
            new Employee("Anil", "Trading", 1500000),   // ties Sneha on salary
            new Employee("Priya", "Risk", 900000));
        DirectoryService service = new DirectoryService();

        service.sortedDirectory(employees).forEach(e ->
            log.info(() -> e.getDepartment() + " | " + e.getSalary() + " | " + e.getName()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
            this.name = name;
            this.department = department
            this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/DirectoryService.java ───
class DirectoryService {
    List<Employee> sortedDirectory(List<Employee> employees) {
        Comparator<Employee> order = Comparator
            .comparing(Employee::getDepartment)                               // dept asc
            .thenComparing(Comparator.comparingDouble(Employee::getSalary).reversed()) // salary desc
            .thenComparing(Employee::getName);                                // name asc (tie-break)
        return employees.stream()
            .sorted(order)
            .collect(java.util.stream.Collectors.toList());
    }
}
